DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM research.final_dataset_candidate
    ) THEN
        RAISE EXCEPTION 'Candidate dataset is empty';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM research.final_dataset_candidate AS d
        CROSS JOIN LATERAL (
            VALUES
                (d.research_id::text),
                (d.university::text),
                (d.title::text),
                (d.authors::text),
                (d.publication_year::text),
                (d.doi::text),
                (d.url::text),
                (d.source::text)
        ) AS required_values(value)
        WHERE value IS NULL
           OR lower(btrim(value)) IN (
               '', 'n/a', 'na', 'nan',
               'none', 'null', '<na>', 'nat'
           )
    ) THEN
        RAISE EXCEPTION 'Missing mandatory values';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM research.final_dataset_candidate
        WHERE university NOT IN (
            'KAUST', 'KFUPM', 'KSU', 'KAU', 'KKU', 'PSAU'
        )
    ) THEN
        RAISE EXCEPTION 'Unexpected university';
    END IF;

    IF (
        SELECT COUNT(DISTINCT university)
        FROM research.final_dataset_candidate
    ) <> 6 THEN
        RAISE EXCEPTION 'Expected all six universities';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM research.final_dataset_candidate
        WHERE publication_year NOT BETWEEN 2023 AND 2026
           OR publication_year <> trunc(publication_year::numeric)
    ) THEN
        RAISE EXCEPTION 'Invalid publication year';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM research.final_dataset_candidate
        WHERE doi !~* '^10\.[0-9]{4,9}/[^[:space:]]+$'
    ) THEN
        RAISE EXCEPTION 'Invalid DOI format';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM research.final_dataset_candidate
        WHERE url !~* '^https?://[^/?#[:space:]]+'
           OR url ~ '[[:space:]]'
    ) THEN
        RAISE EXCEPTION 'Invalid URL format';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM research.final_dataset_candidate
        WHERE publication_date IS NOT NULL
          AND EXTRACT(YEAR FROM publication_date) <> publication_year
    ) THEN
        RAISE EXCEPTION 'Publication date/year mismatch';
    END IF;

    IF EXISTS (
        SELECT research_id
        FROM research.final_dataset_candidate
        GROUP BY research_id
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Duplicate research_id';
    END IF;

    IF EXISTS (
        SELECT university, lower(btrim(doi))
        FROM research.final_dataset_candidate
        GROUP BY university, lower(btrim(doi))
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Duplicate DOI within university';
    END IF;
END $$;
